sp_widget.css:
.ibar-kpi-card { text-align: center; padding: 16px 8px; border-radius: 4px; border: 1px solid $border-tertiary; margin-bottom: 16px; background: $background-primary; }
.ibar-kpi-value { font-size: 32px; font-weight: 700; color: $text-color; line-height: 1.2; }
.ibar-kpi-label { font-size: 12px; color: $text-muted; text-transform: uppercase; letter-spacing: 0.04em; margin-top: 4px; }
.ibar-kpi-info { border-left: 3px solid $brand-info; } .ibar-kpi-warning { border-left: 3px solid $brand-warning; } .ibar-kpi-success { border-left: 3px solid $brand-success; }

sp_widget.script:
(function() { data.statuses = { pending: 0, in_progress: 0, completed: 0 };
  try { var gr = new GlideRecord("x_1433041_identi_0_application"); gr.addQuery("questionnaire_status", "build_ready"); gr.addQuery("active", true); gr.setLimit(100); gr.query();
    while (gr.next()) { data.statuses.pending++; }
    var gr2 = new GlideRecord("x_1433041_identi_0_application"); gr2.addQuery("questionnaire_status", "completed"); gr2.addQuery("active", true); gr2.setLimit(100); gr2.query();
    while (gr2.next()) { data.statuses.completed++; }
  } catch (e) { gs.error("IBAR Build Status widget error: " + e.message); }
})();
